const now = new Date();
const eastern = new Date(now.toLocaleString('en-US', { timeZone: 'America/New_York' }));
const hour = eastern.getHours();
const isBusinessHours = hour >= 8 && hour < 20;
return [{ json: { isBusinessHours, currentHour: hour, timestamp: now.toISOString() } }];

const now = new Date();
const twoHoursAgo = new Date(now.getTime() - 2 * 60 * 60 * 1000).toISOString();
const fortyEightHoursAgo = new Date(now.getTime() - 48 * 60 * 60 * 1000).toISOString();
const seventyTwoHoursAgo = new Date(now.getTime() - 72 * 60 * 60 * 1000).toISOString();
return [{ json: { twoHoursAgo, fortyEightHoursAgo, seventyTwoHoursAgo, now: now.toISOString() } }];

const items = $input.all().map(i => i.json);
const dealArr = Array.isArray(items) && items.length > 0 && items[0].id ? items : [];
if (dealArr.length === 0) return [];

return dealArr.map(deal => {
  const sentAt = new Date(deal.confirmation_sent_at);
  const hoursAgo = Math.round((Date.now() - sentAt.getTime()) / (1000 * 60 * 60));
  return {
    json: {
      dealId: deal.id,
      staffId: deal.staff_id,
      message: `\u23f0 Still need to confirm that ${deal.package.replace(/_/g, ' ')} deal for ${deal.athlete_name}? Reply YES or CANCEL. (${hoursAgo}h ago)`,
      athleteName: deal.athlete_name,
      package: deal.package
    }
  };
});

