const items = $input.all().map(i => i.json);
const dealArr = Array.isArray(items) && items.length > 0 && items[0].id ? items : [];
if (dealArr.length === 0) return [];

return dealArr.map(deal => {
  const updatedAt = new Date(deal.updated_at);
  const daysAgo = Math.round((Date.now() - updatedAt.getTime()) / (1000 * 60 * 60 * 24));
  const price = (deal.price_cents / 100).toFixed(0);
  return {
    json: {
      dealId: deal.id,
      staffId: deal.staff_id,
      message: `\ud83d\udcb0 ${deal.athlete_name} signed but hasn't paid for ${deal.package.replace(/_/g, ' ')} ($${price}) \u2014 ${daysAgo} days. Follow up?`,
      athleteName: deal.athlete_name,
      package: deal.package,
      priceCents: deal.price_cents
    }
  };
});

const deals = $input.all().map(i => i.json);
if (deals.length === 0) return [];

const uniqueStaffIds = [...new Set(deals.map(d => d.staffId))];
const staffFilter = uniqueStaffIds.map(id => `id.eq.${id}`).join(',');

const response = await this.helpers.httpRequest({
  method: 'GET',
  url: `${process.env.SUPABASE_URL}/rest/v1/users?or=(${staffFilter})&select=id,phone,name`,
  headers: {
    'apikey': process.env.SUPABASE_SERVICE_KEY,
    'Authorization': `Bearer ${process.env.SUPABASE_SERVICE_KEY}`
  }
});

const staffMap = {};
const staffArr = Array.isArray(response) ? response : [];
staffArr.forEach(s => { staffMap[s.id] = s; });

return deals.map(deal => ({
  json: {
    ...deal,
    staffPhone: staffMap[deal.staffId]?.phone || null,
    staffName: staffMap[deal.staffId]?.name || null
  }
})).filter(item => item.json.staffPhone);

